'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const DB_NAME='lst-lieferschein-praxis-v01',LAST_KEY='lst-praxis-last-draft',VERSION='0.3.0';
const STORES=['drafts','archives','photos','shifts','assignments','meters','fuels','settings'];
const REPORT_FIELDS=['day','report','foreman','worker','abrasive','abrasiveOther','abrasiveKg','airSetting','mediaSetting','nozzle','reportOther','noReportReason'];
const FIELDS=['project','deliveryNumber',...REPORT_FIELDS,'signerName','signedDay','signerRole','lstEmail','customerEmail'];
const INTERNAL_IDS=['timePerson','timeDate','timeEndDate','orderDate','orderEndDate','breakMinutes','orderBreakMinutes','machine','rentalMachine','meterDate','meterStart','meterEnd','fuelDate','fuelMeter','fuelLitres','fuelOther'];
const STATUS_LABELS={pending:'Anstehend',active:'In Arbeit',done:'Abgeschlossen'};
const canvas=$('#signature'),ctx=canvas.getContext('2d');
let db,draftId,createdAt,sourcePdf=null,hasInk=false,activePointer=null,activeArchive=null,saveTimer,revision=0,applying=false,viewBusy=false,jobStatus='pending',hasActivity=false;
let days=[],dayId,meta={},packageInfo=null,phase='prep',closePrepared=false,renumberOriginal=false;
let saveQueue=Promise.resolve(),pendingSaveError=null,editTimeId=null,editMeterId=null,editFuelId=null,pdfModulePromise,previewDoc=null,previewPage=1,previewReturn='close';
let wheelControls={},pendingWheelValues={},renderingPdf=false;
ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle='#132c41';
function say(text,error=false){$('#status').textContent=text;$('#status').className=error?'error':''}
function today(){const d=new Date(),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())}
function uuid(){return crypto.randomUUID()}
function dayAfter(date){const d=new Date((date||today())+'T12:00:00');d.setDate(d.getDate()+1);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function validDate(v){return /^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(new Date(v+'T12:00:00'))&&new Date(v+'T12:00:00').toISOString().slice(0,10)===v}
function remember(){try{localStorage.setItem(LAST_KEY,draftId)}catch{}}
function openDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,2);r.onupgradeneeded=()=>{for(const name of STORES)if(!r.result.objectStoreNames.contains(name))r.result.createObjectStore(name,{keyPath:'id'})};r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();say('Bitte andere App-Fenster schließen und diese App neu öffnen.',true);$('#editor').disabled=true};resolve(r.result)};r.onerror=()=>reject(r.error);r.onblocked=()=>say('Für das Update bitte alle anderen Fenster dieser App schließen.',true)})}
function readStore(name,id){return new Promise((resolve,reject)=>{const s=db.transaction(name).objectStore(name),r=id===undefined?s.getAll():s.get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function writeRecords(records){return new Promise((resolve,reject)=>{const t=db.transaction([...new Set(records.map(r=>r.store))],'readwrite');for(const r of records){const s=t.objectStore(r.store);if(r.remove)s.delete(r.id);else s.put(r.value)}t.oncomplete=resolve;t.onabort=()=>reject(t.error||new Error('Speicherung abgebrochen'));t.onerror=()=>reject(t.error)})}
function newDay(date= today(),previous={}){return {id:uuid(),date,fields:Object.fromEntries(REPORT_FIELDS.map(k=>[k,k==='day'?date:['foreman','worker','abrasive','abrasiveOther','airSetting','mediaSetting','nozzle'].includes(k)?previous[k]||'':''])),baseQuantity:false,noReportNeeded:false}}
function currentDay(){return days.find(d=>d.id===dayId)}
function captureDay(){const d=currentDay();if(!d)return;d.fields=Object.fromEntries(REPORT_FIELDS.map(id=>[id,$('#'+id).value]));d.date=d.fields.day;d.baseQuantity=$('#baseQuantity').checked;d.noReportNeeded=$('#noReportNeeded').checked}
function readDraft(){captureDay();const internal=Object.fromEntries(INTERNAL_IDS.map(id=>[id,$('#'+id).value]));for(const id of ['workStart','workEnd','orderStart','orderEnd'])internal[id]=wheelValue(id);return {id:draftId,createdAt,updatedAt:new Date().toISOString(),version:VERSION,status:jobStatus,hasActivity,sourcePdf,fields:Object.fromEntries(FIELDS.map(id=>[id,$('#'+id).value])),days:structuredClone(days),dayId,meta:Object.fromEntries($$('[data-meta]').map(el=>[el.dataset.meta,el.value])),metaConfirmed:$('#metaConfirmed').checked,packageInfo,phase,closePrepared,internal,shippingChoice:$('#shippingChoice').value,originalPages:Number($('#originalPages').value)||null,renumberOriginal:$('#renumberOriginal').checked,baseQuantity:$('#baseQuantity').checked,signMode:$('#signMode').value,hasInk,signature:hasInk?canvas.toDataURL('image/png'):null}}
function emptyDraft(){return {id:uuid(),createdAt:new Date().toISOString(),sourcePdf:null,status:'pending',fields:{day:today(),signedDay:today(),lstEmail:'jobs@lueke-strahlt.de'},days:[newDay()],shippingChoice:'none'}}
function hasJob(d){return !!(d.sourcePdf||d.packageInfo||d.fields?.project?.trim()||d.days?.some(x=>x.fields?.report?.trim())||d.hasActivity||Object.values(d.meta||{}).some(v=>String(v).trim()))}
function statusFor(d,archives=[]){if(STATUS_LABELS[d.status])return d.status;return archives.some(a=>a.draftId===d.id&&a.snapshot?.signature===d.signature&&a.snapshot?.fields?.report===d.fields?.report)?'done':d.fields?.report?.trim()?'active':'pending'}
function scheduleSave(){if(applying||!db||!draftId)return;clearTimeout(saveTimer);$('#saveState').textContent='Änderungen werden gespeichert …';saveTimer=setTimeout(()=>saveDraft().catch(()=>{}),400)}
function saveDraft(){clearTimeout(saveTimer);if(!db||!draftId)return Promise.resolve();const data=readDraft(),rev=revision;saveQueue=saveQueue.catch(()=>{}).then(async()=>{await writeRecords([{store:'drafts',value:data}]);pendingSaveError=null;if(data.id===draftId){remember();if(rev===revision)$('#saveState').textContent='Lokal gespeichert: '+new Date().toLocaleTimeString('de-DE')}await refreshDrafts();return data}).catch(e=>{pendingSaveError=e;say('Speichern fehlgeschlagen. Bitte vor dem Schließen sichern: '+e.message,true);throw e});return saveQueue}
async function flushSave(){clearTimeout(saveTimer);await saveDraft();if(pendingSaveError)throw pendingSaveError}
async function busy(fn){if(viewBusy)return;viewBusy=true;$('#editor').disabled=true;for(const id of ['openNewJob','loadDemo','backToJobs','addDay','daySelector'])$('#'+id).disabled=true;try{return await fn()}catch(e){say(e.message||'Vorgang fehlgeschlagen.',true)}finally{viewBusy=false;$('#editor').disabled=false;for(const id of ['openNewJob','loadDemo','backToJobs','addDay','daySelector'])$('#'+id).disabled=false}}
function clearSignature(){ctx.clearRect(0,0,canvas.width,canvas.height);hasInk=false;activePointer=null}
async function drawSignature(data){clearSignature();if(!data)return;const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('Unterschrift nicht lesbar'));img.src=data});ctx.drawImage(img,0,0,canvas.width,canvas.height);hasInk=true}
function clearActiveArchive(){activeArchive=null;$('#archives').value='';$('#archiveInfo').textContent='Noch keine Fassung ausgewählt. Frühere Fassungen bleiben im Archiv erhalten.';for(const id of ['viewPdf','downloadPdf','downloadDocumentation','copyEmails','sharePdf','copyOfficeEmail','shareOffice','downloadOfficePackage','sendLstEmail','sendCustomerEmail'])$('#'+id).disabled=true;$('#sendLstEmail').value='';$('#sendCustomerEmail').value=''}
function invalidateCustomer(reason='Kundenangaben geändert. Bitte vor dem Abschluss erneut prüfen und unterschreiben.'){if(hasInk)clearSignature();closePrepared=false;if(jobStatus==='done')jobStatus='active';clearActiveArchive();revision++;updateHeading();$('#closeState').textContent=reason;scheduleSave()}
function renderSource(count){$('#originalPages').replaceChildren();if(!sourcePdf){$('#originalPages').append(new Option('Zuerst PDF auswählen',''));$('#sourceInfo').textContent='Noch kein Lieferschein ausgewählt.';$('#viewOriginal').disabled=true;return}for(let n=1;n<=sourcePdf.pages;n++)$('#originalPages').append(new Option(n===sourcePdf.pages?'Alle '+n+' Originalseiten':'Erste '+n+' Originalseite(n)',n));$('#originalPages').value=String(count||sourcePdf.pages);$('#sourceInfo').textContent=sourcePdf.name+' · '+sourcePdf.pages+' Seite(n) · Original lokal gespeichert';$('#viewOriginal').disabled=false}
function updateHeading(){$('#jobTitle').textContent=$('#project').value||'Neuer Job';$('#jobBadge').textContent=STATUS_LABELS[jobStatus];$('#jobBadge').dataset.status=jobStatus;$('#jobStatus').value=jobStatus}
function renderDays(){const sel=$('#daySelector');sel.replaceChildren();for(const d of [...days].sort((a,b)=>a.date.localeCompare(b.date)))sel.append(new Option(formatReportDay(d.date)+(d.fields.report?.trim()?' · Bericht vorhanden':d.noReportNeeded?' · ohne Kundenbericht':' · Bericht offen'),d.id));sel.value=dayId;$('#dayReportState').textContent='Arbeitsbericht für '+formatReportDay(currentDay()?.date)+' · '+days.length+' Arbeitstag(e) im Job'}
function loadDayFields(){const d=currentDay();for(const id of REPORT_FIELDS)$('#'+id).value=d?.fields[id]||'';$('#baseQuantity').checked=!!d?.baseQuantity;$('#noReportNeeded').checked=!!d?.noReportNeeded;renderDays()}
async function applyDraft(d){applying=true;draftId=d.id;createdAt=d.createdAt;sourcePdf=d.sourcePdf||null;hasActivity=!!d.hasActivity;jobStatus=statusFor(d,await readStore('archives'));days=d.days?.length?structuredClone(d.days):[{...newDay(d.fields?.day||today()),fields:{...newDay(d.fields?.day||today()).fields,...Object.fromEntries(REPORT_FIELDS.map(k=>[k,d.fields?.[k]||'']))},date:d.fields?.day||today(),baseQuantity:!!d.baseQuantity}];dayId=days.some(x=>x.id===d.dayId)?d.dayId:days[0].id;for(const id of FIELDS)$('#'+id).value=d.fields?.[id]||'';$('#lstEmail').value=d.fields?.lstEmail||'jobs@lueke-strahlt.de';$('#signedDay').value=d.fields?.signedDay||today();meta=d.meta||{};packageInfo=d.packageInfo||null;for(const el of $$('[data-meta]'))el.value=meta[el.dataset.meta]||'';$('#metaConfirmed').checked=!!d.metaConfirmed;$('#shippingChoice').value=d.shippingChoice||'none';$('#signMode').value=d.signMode||'pen';$('#renumberOriginal').checked=!!d.renumberOriginal;closePrepared=!!d.closePrepared||jobStatus==='done';phase=jobStatus==='done'?'close':d.phase||'prep';loadDayFields();renderSource(d.originalPages);for(const id of INTERNAL_IDS)$('#'+id).value=d.internal?.[id]??(['timeDate','timeEndDate','orderDate','orderEndDate','meterDate','fuelDate'].includes(id)?currentDay().date:['breakMinutes','orderBreakMinutes'].includes(id)?'0':id==='machine'?'atlas':'');pendingWheelValues={};for(const id of ['workStart','workEnd','orderStart','orderEnd'])setWheelTime(id,d.internal?.[id]||'');$('#meterConfirmed').checked=false;$('#updateShift').checked=false;editTimeId=editMeterId=editFuelId=null;$('#photoBeforeDate').value=$('#photoAfterDate').value=currentDay().date;await drawSignature(d.hasInk?d.signature:null);clearActiveArchive();$('#sourcePdf').value='';$('#projectPackage').value='';updateHeading();renderSite();toggleInternalFields();revision++;applying=false;remember();$('#saveState').textContent='Job lokal geladen.';await refreshNames();await refreshHistories();await renderPhotos()}
function showJob(){$('#homeView').hidden=true;$('#jobView').hidden=false;$('#pdfPreview').hidden=true;$('#jobBody').hidden=false;updateHeading();showPanel(phase,false);window.scrollTo(0,0);$('#jobTitle').focus()}
function showPanel(name,save=true){phase=name;for(const el of $$('.workflow-panel'))el.hidden=el.dataset.panel!==name;for(const el of $$('.phase-tabs [data-go]')){const group=['before','after','times','compressor','report'].includes(name)?'run':name;el.classList.toggle('selected',el.dataset.go===group);el.setAttribute('aria-current',el.dataset.go===group?'step':'false')}if(name==='times')hydrateWheels();if(name==='run')renderSite();if(name==='close')$('#closeState').textContent=jobStatus==='done'?'Endgültige Fassung archiviert. Büroübergabe und gewünschte Kopie getrennt durchführen.':closePrepared?'Berichte vorbereitet. Vorschau prüfen und einmal am Auftragsende unterschreiben.':'Vor dem Unterschreiben alle Tagesberichte über „Abschluss vorbereiten“ prüfen.';if(save)scheduleSave();window.scrollTo(0,0)}
async function openJob(id){await busy(async()=>{await flushSave();const d=await readStore('drafts',id);if(!d)throw Error('Job nicht gefunden');await applyDraft(d);await refreshArchives();showJob();say('Job geöffnet. Änderungen werden lokal gespeichert.')})}
async function refreshDrafts(){const [all,archives]=await Promise.all([readStore('drafts'),readStore('archives')]);for(const [state,suffix] of [['pending','Pending'],['active','Active'],['done','Done']]){const list=$('#jobs'+suffix),jobs=all.filter(hasJob).filter(d=>statusFor(d,archives)===state).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));list.replaceChildren();$('#count'+suffix).textContent=jobs.length;for(const d of jobs){const b=document.createElement('button');b.type='button';b.className='job-card';for(const [tag,text] of [['strong',d.fields.project||'Unbenannter Job'],['span',(d.fields.deliveryNumber||'')+' · '+(d.days?.length||1)+' Arbeitstag(e)'],['span',state==='done'?'Dokumente und Büroübergabe →':'Job öffnen →']]){const e=document.createElement(tag);e.textContent=text;b.append(e)}b.onclick=()=>openJob(d.id);list.append(b)}if(!jobs.length){const p=document.createElement('p');p.className='empty-jobs';p.textContent={pending:'Hier erscheinen deine nächsten Jobs.',active:'Noch kein Job in Bearbeitung.',done:'Hier findest du abgeschlossene Jobs.'}[state];list.append(p)}}$('#jobSummary').textContent=all.filter(hasJob).length+' gespeicherte Jobs · lokaler Testbetrieb'}
$('#form').onsubmit=e=>e.preventDefault();
for(const b of $$('[data-go]'))b.onclick=()=>{if(viewBusy)return;showPanel(b.dataset.go)};
$('#openNewJob').onclick=()=>busy(async()=>{await flushSave();await applyDraft(emptyDraft());await refreshArchives();showJob();say('Neuer Testjob. Lieferschein auswählen und Vorbereitung ergänzen.')});
$('#backToJobs').onclick=()=>busy(async()=>{await flushSave();await refreshDrafts();$('#jobView').hidden=true;$('#homeView').hidden=false;window.scrollTo(0,0);$('#homeTitle').focus();say('Jobs lokal gespeichert. Notion und Mac mini sind noch nicht verbunden.')});
$('#startJob').onclick=()=>{if(jobStatus==='pending')jobStatus='active';updateHeading();showPanel('run');scheduleSave()};
$('#jobStatus').onchange=()=>{if($('#jobStatus').value==='done'&&jobStatus!=='done')return;jobStatus=$('#jobStatus').value;revision++;updateHeading();scheduleSave()};
$('#editor').addEventListener('input',e=>{if(applying||e.target.type==='file'||e.target.id==='jobStatus')return;const id=e.target.id;revision++;if(REPORT_FIELDS.includes(id)||['baseQuantity','noReportNeeded','project','deliveryNumber','originalPages','renumberOriginal'].includes(id)){if(id==='day'){const dup=days.find(d=>d.id!==dayId&&d.date===e.target.value);if(dup){e.target.value=currentDay().date;say('Für dieses Datum gibt es bereits einen Arbeitstag. Bitte oben auswählen.',true);return}}invalidateCustomer();captureDay();renderDays()}else if(['signerName','signedDay','signerRole'].includes(id)){if(hasInk)clearSignature();if(jobStatus==='done')jobStatus='active';clearActiveArchive()}updateHeading();if(e.target.dataset.meta||id==='metaConfirmed')renderSite();scheduleSave()});
$('#daySelector').onchange=()=>busy(async()=>{captureDay();dayId=$('#daySelector').value;loadDayFields();for(const id of ['timeDate','timeEndDate','orderDate','orderEndDate','meterDate','fuelDate','photoBeforeDate','photoAfterDate'])$('#'+id).value=currentDay().date;$('#meterConfirmed').checked=false;await suggestMeter();await saveDraft();await refreshHistories();await renderPhotos();say('Arbeitstag '+formatReportDay(currentDay().date)+' geöffnet.')});
$('#addDay').onclick=()=>busy(async()=>{captureDay();let date=dayAfter(days.reduce((a,d)=>d.date>a?d.date:a,days[0]?.date||today()));if(days.length===1&&days[0].date<today())date=dayAfter(days[0].date);while(days.some(d=>d.date===date))date=dayAfter(date);const d=newDay(date,currentDay()?.fields);if($('#signedDay').value<date)$('#signedDay').value=date;days.push(d);dayId=d.id;invalidateCustomer('Neuer Arbeitstag angelegt. Abschluss später gemeinsam erstellen.');loadDayFields();for(const id of ['timeDate','timeEndDate','orderDate','orderEndDate','meterDate','fuelDate','photoBeforeDate','photoAfterDate'])$('#'+id).value=date;editTimeId=editMeterId=editFuelId=null;for(const id of Object.keys(wheelControls))setWheelTime(id,'');$('#meterEnd').value='';$('#meterConfirmed').checked=false;await suggestMeter();showPanel('report');await saveDraft();say('Weiterer Arbeitstag angelegt. Datum bei Bedarf ändern.')});
$('#saveDraft').onclick=()=>busy(async()=>{await rememberName($('#foreman').value);await flushSave();renderDays();say('Arbeitsbericht und alle Tagesangaben lokal gespeichert.')});
function ensureDay(date){if(!days.some(d=>d.date===date))days.push(newDay(date,currentDay()?.fields))}
function allowed(e){return $('#signMode').value==='both'||e.pointerType==='pen'}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height]}
canvas.onpointerdown=e=>{if(activePointer!==null||viewBusy||!allowed(e))return;e.preventDefault();activePointer=e.pointerId;canvas.setPointerCapture(e.pointerId);if(jobStatus==='done')jobStatus='active';updateHeading();clearActiveArchive();const [x,y]=point(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.1,y+.1);ctx.stroke();hasInk=true;revision++};canvas.onpointermove=e=>{if(e.pointerId!==activePointer)return;e.preventDefault();ctx.lineTo(...point(e));ctx.stroke()};for(const event of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(event,e=>{if(e.pointerId===activePointer){activePointer=null;scheduleSave()}});
$('#clearSignature').onclick=()=>{if(jobStatus==='done')jobStatus='active';updateHeading();clearSignature();clearActiveArchive();revision++;scheduleSave();say('Unterschrift im Entwurf gelöscht. Archivierte Fassungen bleiben erhalten.')};
function toBase64(bytes){let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary)}
function fromBase64(s){return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
function pdfBlob(s){return new Blob([fromBase64(s)],{type:'application/pdf'})}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000)}
async function pdfModule(){return pdfModulePromise||(pdfModulePromise=import('./pdf.min.mjs').then(m=>{m.GlobalWorkerOptions.workerSrc=new URL('./pdf.worker.min.mjs',location.href).href;return m}).catch(e=>{pdfModulePromise=null;throw Error('PDF-Vorschau konnte nicht geladen werden. App einmal online vollständig öffnen. '+e.message)}))}
async function pdfTextPages(bytes){const m=await pdfModule(),task=m.getDocument({data:bytes.slice(),isEvalSupported:false,useSystemFonts:true,standardFontDataUrl:new URL('./',location.href).href});const doc=await task.promise;try{const out=[];for(let n=1;n<=doc.numPages;n++){const page=await doc.getPage(n),content=await page.getTextContent();out.push(content.items.map(i=>i.str+(i.hasEOL?'\n':' ')).join(''))}return out}finally{await doc.destroy()}}
$('#sourcePdf').onchange=()=>{const f=$('#sourcePdf').files[0];if(!f)return;busy(async()=>{try{const bytes=new Uint8Array(await f.arrayBuffer()),pdf=await PDFLib.PDFDocument.load(bytes);if(!pdf.getPageCount())throw Error('Die PDF hat keine Seiten.');await flushSave();if(sourcePdf){await applyDraft(emptyDraft())}sourcePdf={name:f.name,data:toBase64(bytes),pages:pdf.getPageCount()};$('#project').value=projectFromFilename(f.name);$('#deliveryNumber').value=(f.name.match(/LS\d+/i)||[''])[0].toUpperCase();let count=sourcePdf.pages;try{const texts=await pdfTextPages(bytes);if(count===3&&/Arbeitsnachweis/i.test(texts[2])){count=2;$('#renumberOriginal').checked=true}}catch{}renderSource(count);invalidateCustomer();await saveDraft();await refreshArchives();showJob();showPanel('prep');say('Lieferschein übernommen. Originalseiten und Einsatzdaten prüfen.')}catch(e){say('PDF nicht übernommen: '+e.message,true)}finally{$('#sourcePdf').value=''}})};
$('#viewOriginal').onclick=()=>{if(sourcePdf)showPdf(fromBase64(sourcePdf.data),'Original-Lieferschein','prep',false)};
function renderSite(){const fields=Object.fromEntries($$('[data-meta]').map(e=>[e.dataset.meta,e.value]));const info=$('#siteInfo');info.replaceChildren();for(const [key,label] of [['client','Auftraggeber / Rechnungsempfänger'],['siteName','Betrieb vor Ort'],['location','Einsatzort'],['contact','Ansprechpartner'],['phone','Telefon'],['tasks','Arbeitsauftrag'],['packing','Mitnehmen'],['conditions','Besonderheiten vor Ort']]){const item=document.createElement('div');item.className='site-item';const strong=document.createElement('strong');strong.textContent=label;const value=document.createElement('p');value.textContent=fields[key]||'Offen – noch keine Angabe';if(!fields[key])value.className='missing';item.append(strong,value);if(key==='phone'&&fields[key]){for(const number of fields[key].split(/[,;\n]+/)){const digits=number.replace(/[^+\d]/g,'');if(digits.length>=5){const a=document.createElement('a');a.textContent='Anrufen: '+number.trim();a.href='tel:'+digits;item.append(a)}}}if(key==='location'&&fields[key]){const a=document.createElement('a');a.textContent='Zum Einsatzort navigieren';a.href='https://maps.apple.com/?daddr='+encodeURIComponent(fields[key]);a.target='_blank';a.rel='noopener';item.append(a)}info.append(item)}const origin=packageInfo?'Projektpaket '+packageInfo.revision+' · '+new Date(packageInfo.importedAt).toLocaleString('de-DE'):'Manuell vorbereiteter Testjob';$('#infoProvenance').textContent=origin+($('#metaConfirmed').checked?' · Einsatzangaben geprüft':' · Einsatzangaben noch prüfen');$('#projectPdfInfo').textContent=origin+(packageInfo?.missing?.length?' · Offen: '+packageInfo.missing.join(', '):'');}
$('#foremanPick').onchange=()=>{if($('#foremanPick').value){$('#foreman').value=$('#foremanPick').value;$('#foreman').dispatchEvent(new Event('input',{bubbles:true}))}};$('#timePersonPick').onchange=()=>{if($('#timePersonPick').value){$('#timePerson').value=$('#timePersonPick').value;$('#timePerson').dispatchEvent(new Event('input',{bubbles:true}))}};
async function rememberName(name){name=name.trim();if(!name)return;await writeRecords([{store:'settings',value:{id:'person:'+name.toLocaleLowerCase('de-DE'),name}}]);await refreshNames()}
async function refreshNames(){const settings=await readStore('settings'),names=[...new Set(['Matthias','Faro',...settings.filter(s=>s.id.startsWith('person:')).map(s=>s.name)])].sort();$('#foremanNames').replaceChildren(...names.map(n=>new Option(n,n)));$('#foremanPick').replaceChildren(new Option('Gespeicherten Namen wählen',''),...names.map(n=>new Option(n,n)));$('#timePersonPick').replaceChildren(new Option('Mitarbeiter wählen',''),...names.map(n=>new Option(n,n)));const machines=[...new Set((await readStore('meters')).filter(x=>x.machineId!=='atlas').map(x=>x.machineName))];$('#machineNames').replaceChildren(...machines.map(n=>new Option(n,n)))}
// Accessible scroll wheels: the available minute values are always quarter hours.
function createWheel(values,label,onChange){const root=document.createElement('div');root.className='wheel-column';root.tabIndex=0;root.setAttribute('role','listbox');root.setAttribute('aria-label',label);const pad=document.createElement('div');pad.className='wheel-pad';pad.setAttribute('aria-hidden','true');root.append(pad);const options=values.map((v,i)=>{const e=document.createElement('div');e.className='wheel-option';e.setAttribute('role','option');e.id='wheel-'+uuid();e.textContent=v||'–';e.onclick=()=>{control.set(v);onChange()};root.append(e);return e});root.append(pad.cloneNode());let suppressed=false;const control={root,value:'',set(v){this.value=values.includes(v)?v:'';suppressed=true;root.scrollTop=values.indexOf(this.value)*44;this.mark();requestAnimationFrame(()=>{suppressed=false})},mark(){const index=values.indexOf(this.value);options.forEach((e,i)=>e.setAttribute('aria-selected',i===index?'true':'false'));root.setAttribute('aria-activedescendant',options[index].id)}};root.onscroll=()=>{if(suppressed||!root.getClientRects().length)return;const index=Math.max(0,Math.min(values.length-1,Math.round(root.scrollTop/44)));if(values[index]!==control.value){control.value=values[index];control.mark();onChange()}};root.onkeydown=e=>{let i=values.indexOf(control.value);if(e.key==='ArrowDown')i++;else if(e.key==='ArrowUp')i--;else if(e.key==='Home')i=0;else if(e.key==='End')i=values.length-1;else return;e.preventDefault();control.set(values[Math.max(0,Math.min(values.length-1,i))]);onChange()};control.mark();return control}
function initWheels(){for(const id of ['workStart','workEnd','orderStart','orderEnd']){const onChange=()=>{if(!applying){revision++;scheduleSave();calculateTime()}};const hours=createWheel(['',...Array.from({length:24},(_,i)=>String(i).padStart(2,'0'))],$('#'+id).previousElementSibling.textContent+' Stunden',onChange),minutes=createWheel(['','00','15','30','45'],'Minuten in 15-Minuten-Schritten',onChange);const holder=$('#'+id);holder.append(hours.root,document.createTextNode(':'),minutes.root);wheelControls[id]={hours,minutes}}}
function setWheelTime(id,value){const c=wheelControls[id];if(!c)return;const parts=(value||'').split(':');c.hours.set(parts[0]||'');c.minutes.set(parts[1]||'');pendingWheelValues[id]=value||''}
function wheelValue(id){const c=wheelControls[id];return c?.hours.value&&c?.minutes.value?c.hours.value+':'+c.minutes.value:''}
function hydrateWheels(){for(const c of Object.values(wheelControls)){c.hours.set(c.hours.value);c.minutes.set(c.minutes.value)}}
function duration(ms){return Math.floor(ms/3600000)+' h '+String(Math.round(ms/60000)%60).padStart(2,'0')+' min'}
function instant(date,time){if(!validDate(date)||!/^([01]\d|2[0-3]):(00|15|30|45)$/.test(time))throw Error('Datum und Uhrzeiten vollständig in 15-Minuten-Schritten wählen.');const value=new Date(date+'T'+time+':00');if(value.getHours()!==Number(time.slice(0,2)))throw Error('Diese Ortszeit existiert wegen der Zeitumstellung nicht.');return value.getTime()}
function timeInput(){const person=$('#timePerson').value.trim();if(!person)throw Error('Bitte den Mitarbeiter angeben.');const ws=instant($('#timeDate').value,wheelValue('workStart')),we=instant($('#timeEndDate').value,wheelValue('workEnd')),os=instant($('#orderDate').value,wheelValue('orderStart')),oe=instant($('#orderEndDate').value,wheelValue('orderEnd'));const pause=Number($('#breakMinutes').value)*60000,orderPause=Number($('#orderBreakMinutes').value)*60000;if(we<=ws||we-ws>24*3600000)throw Error('Arbeitsende muss nach Arbeitsbeginn liegen, höchstens 24 Stunden später.');if(os<ws||oe>we||oe<=os)throw Error('Der Auftragsabschnitt muss vollständig innerhalb der Tagesarbeitszeit liegen.');if(pause>=we-ws||orderPause>=oe-os||orderPause>pause)throw Error('Pausen prüfen: Auftragspause darf die Tagespause nicht überschreiten und muss kürzer als der Abschnitt sein.');return {person,personId:person.toLocaleLowerCase('de-DE'),date:$('#timeDate').value,orderDate:$('#orderDate').value,ws,we,os,oe,pause,orderPause}}
function calculateTime(){try{const t=timeInput();$('#timeCalculation').textContent='Tagesarbeitszeit netto: '+duration(t.we-t.ws-t.pause)+' · Auftragsabschnitt netto: '+duration(t.oe-t.os-t.orderPause)}catch(e){$('#timeCalculation').textContent=e.message}}
