async function saveTime(){await busy(async()=>{const t=timeInput(),[shifts,assignments]=await Promise.all([readStore('shifts'),readStore('assignments')]),shiftId=t.personId+'|'+t.date,old=shifts.find(s=>s.id===shiftId);if(old&&(old.start!==t.ws||old.end!==t.we||old.pause!==t.pause)&&!$('#updateShift').checked)throw Error('Für diese Person gibt es bereits eine Tagesarbeitszeit. Gleiche Werte übernehmen oder „bewusst aktualisieren“ aktivieren.');for(const s of shifts)if(s.id!==shiftId&&s.personId===t.personId&&s.start<t.we&&s.end>t.ws)throw Error('Die Tagesarbeitszeit überschneidet sich mit einer anderen gespeicherten Schicht.');for(const a of assignments){if(a.id===editTimeId)continue;if(a.personId===t.personId&&a.start<t.oe&&a.end>t.os)throw Error('Der Auftragsabschnitt überschneidet sich mit einem anderen Eintrag dieser Person: '+a.jobName);if(a.shiftId===shiftId&&(a.start<t.ws||a.end>t.we))throw Error('Die geänderte Tagesarbeitszeit würde einen gespeicherten Auftragsabschnitt ausschließen.')}const otherBreaks=assignments.filter(a=>a.shiftId===shiftId&&a.id!==editTimeId).reduce((s,a)=>s+a.pause,0);if(otherBreaks+t.orderPause>t.pause)throw Error('Die Auftragspausen dieses Tages überschreiten zusammen die Tagespause.');const now=new Date().toISOString(),assignment={id:editTimeId||uuid(),jobId:draftId,jobName:$('#project').value||'Unbenannter Job',shiftId,personId:t.personId,person:t.person,date:t.orderDate,start:t.os,end:t.oe,pause:t.orderPause,updatedAt:now};await writeRecords([{store:'shifts',value:{id:shiftId,personId:t.personId,person:t.person,date:t.date,start:t.ws,end:t.we,pause:t.pause,updatedAt:now}},{store:'assignments',value:assignment}]);hasActivity=true;ensureDay(t.orderDate);await rememberName(t.person);editTimeId=null;$('#updateShift').checked=false;await saveDraft();await refreshHistories();say('Tagesarbeitszeit einmal je Mitarbeiter/Tag und Auftragsabschnitt lokal gespeichert.')})}
function localParts(ms){const d=new Date(ms),p=n=>String(n).padStart(2,'0');return {date:d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate()),time:p(d.getHours())+':'+p(d.getMinutes())}}
async function editTime(a){if(viewBusy)return;const s=await readStore('shifts',a.shiftId);if(!s)return;editTimeId=a.id;$('#timePerson').value=a.person;for(const [prefix,ms] of [['workStart',s.start],['workEnd',s.end],['orderStart',a.start],['orderEnd',a.end]]){const part=localParts(ms);setWheelTime(prefix,part.time);$('#'+{workStart:'timeDate',workEnd:'timeEndDate',orderStart:'orderDate',orderEnd:'orderEndDate'}[prefix]).value=part.date}$('#breakMinutes').value=String(s.pause/60000);$('#orderBreakMinutes').value=String(a.pause/60000);showPanel('times');calculateTime();say('Gespeicherten Zeiteintrag korrigieren und erneut speichern.')}
