function machineValue(){const rental=$('#machine').value==='rental',name=rental?$('#rentalMachine').value.trim():'Atlas Copco XAHS 186 DD';if(!name)throw Error('Bitte Mietkompressor eindeutig benennen.');return {machineId:rental?'rental:'+name.toLocaleLowerCase('de-DE'):'atlas',machineName:name}}
function decimal(value,label,digits=1){const s=String(value).trim().replace(',','.');if(!new RegExp('^\\d+(?:\\.\\d{1,'+digits+'})?$').test(s))throw Error(label+' als positive Zahl mit höchstens '+digits+' Nachkommastelle(n) eingeben.');const n=Number(s);if(!Number.isFinite(n)||n>1e8)throw Error(label+' ist zu groß.');return n}
