for(const id of ['machine','rentalMachine','meterDate'])$('#'+id).onchange=()=>{toggleInternalFields();suggestMeter().catch(e=>say(e.message,true))};$('#meterStart').addEventListener('input',()=>{$('#meterConfirmed').checked=false;calculateMeter()});$('#meterEnd').addEventListener('input',calculateMeter);$('#fuelLitres').onchange=toggleInternalFields;
$('#saveMeter').onclick=()=>busy(async()=>{const machine=machineValue(),date=$('#meterDate').value,start=decimal($('#meterStart').value,'Anfangsstand'),end=decimal($('#meterEnd').value,'Endstand');if(!validDate(date))throw Error('Bitte Betriebsdatum eintragen.');if(!$('#meterConfirmed').checked)throw Error('Anfangsstand am Gerät prüfen und bestätigen.');if(end<start||end-start>24)throw Error('Laufzeit muss zwischen 0 und 24 Stunden pro Tag liegen.');const rows=await readStore('meters');if(rows.filter(r=>r.id!==editMeterId&&r.machineId===machine.machineId&&r.date===date).reduce((sum,r)=>sum+r.runtime,0)+end-start>24.00001)throw Error('Die Laufzeiten dieses Kompressors überschreiten zusammen 24 Stunden an diesem Tag.');for(const other of rows){if(other.id===editMeterId||other.machineId!==machine.machineId)continue;if(start<other.end&&end>other.start)throw Error('Der Zählerbereich überschneidet sich mit einem gespeicherten Eintrag: '+other.jobName+' · '+formatReportDay(other.date));if(other.date<date&&other.end>start||other.date>date&&other.start<end)throw Error('Zählerstand widerspricht der zeitlichen Reihenfolge gespeicherter Einträge. Bitte ältere Einträge prüfen.')}const previous=rows.find(x=>x.id===editMeterId),now=new Date().toISOString();await writeRecords([{store:'meters',value:{id:editMeterId||uuid(),jobId:draftId,jobName:$('#project').value||'Unbenannter Job',date,...machine,start,end,runtime:Math.round((end-start)*10)/10,confirmed:true,createdAt:previous?.createdAt||now,updatedAt:now}}]);hasActivity=true;ensureDay(date);editMeterId=null;$('#meterEnd').value='';await suggestMeter();await refreshNames();await saveDraft();await refreshHistories();say('Kompressoreintrag dauerhaft im lokalen Speicher gesichert.')});
