async function jpegFromFile(file){if(file.size>40*1024*1024)throw Error('Bild ist größer als 40 MB. Bitte kleinere Aufnahme wählen.');const u=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Bildformat nicht lesbar. Auf dem iPad JPEG/kompatibles Foto wählen.'));img.src=u});const scale=Math.min(1,2048/Math.max(img.naturalWidth,img.naturalHeight)),c=document.createElement('canvas');c.width=Math.round(img.naturalWidth*scale);c.height=Math.round(img.naturalHeight*scale);const g=c.getContext('2d');g.fillStyle='white';g.fillRect(0,0,c.width,c.height);g.drawImage(img,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.86)}finally{URL.revokeObjectURL(u)}}
for(const el of $$('[data-photos]'))el.onchange=()=>{const files=[...el.files],category=el.dataset.photos;if(!files.length)return;busy(async()=>{const date=$('#photo'+(category==='before'?'Before':'After')+'Date').value;if(!validDate(date))throw Error('Bitte Aufnahmedatum eintragen.');const records=[];for(const file of files)records.push({store:'photos',value:{id:uuid(),jobId:draftId,date,category,name:file.name,createdAt:new Date().toISOString(),data:await jpegFromFile(file)}});await writeRecords(records);hasActivity=true;ensureDay(date);invalidateCustomer('Fotodokumentation geändert. Abschlussvorschau neu erstellen.');await saveDraft();await renderPhotos();say(files.length+' Foto(s) lokal gespeichert – '+(category==='before'?'Vorher':'Nachher')+'.')}).finally(()=>{el.value=''})};
async function renderPhotos(){const photos=(await readStore('photos')).filter(p=>p.jobId===draftId).sort((a,b)=>a.date.localeCompare(b.date)||a.createdAt.localeCompare(b.createdAt));for(const cat of ['before','after']){const suffix=cat==='before'?'Before':'After',rows=photos.filter(p=>p.category===cat);$('#'+cat+'Count').textContent='('+rows.length+')';const list=$('#gallery'+suffix);list.replaceChildren();for(const p of rows){const fig=document.createElement('figure'),img=new Image();img.src=p.data;img.alt=(cat==='before'?'Vorher':'Nachher')+' · '+formatReportDay(p.date);img.loading='lazy';const caption=document.createElement('figcaption');caption.textContent=formatReportDay(p.date)+' · '+p.name;fig.append(img,caption);const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent='Foto entfernen';b.onclick=()=>{if(!confirm('Dieses Foto aus der laufenden Jobakte entfernen? Bereits archivierte PDF-Fassungen bleiben erhalten.'))return;busy(async()=>{await writeRecords([{store:'photos',remove:true,id:p.id}]);invalidateCustomer('Foto entfernt. Abschlussvorschau neu erstellen.');await saveDraft();await renderPhotos()})};fig.append(b);list.append(fig)}if(!rows.length)list.textContent='Noch keine Bilder für diesen Bereich.'}}
function reportData(d){return {project:$('#project').value,deliveryNumber:$('#deliveryNumber').value,day:d.date,report:d.fields.report,customer:{...d.fields,baseQuantity:d.baseQuantity}}}
async function validateReports(){captureDay();if(!sourcePdf)throw Error('Bitte einen Lieferschein als PDF auswählen.');if(!$('#project').value.trim())throw Error('Bitte den Auftrag benennen.');if(new Set(days.map(d=>d.date)).size!==days.length)throw Error('Doppelte Tagesdaten gefunden. Arbeitstage zuerst korrigieren.');const count=Number($('#originalPages').value);if(!Number.isInteger(count)||count<1||count>sourcePdf.pages)throw Error('Anzahl der Originalseiten prüfen.');const all=await Promise.all(['photos','assignments','meters','fuels'].map(s=>readStore(s)));const dates=new Set();for(const rows of all)for(const r of rows)if(r.jobId===draftId)dates.add(r.date);const result=[];for(const d of [...days].sort((a,b)=>a.date.localeCompare(b.date))){if(!validDate(d.date))throw Error('Ein Arbeitstag hat kein gültiges Datum.');if(d.noReportNeeded){if(!d.fields.noReportReason?.trim())throw Error('Begründung für den Tag ohne Kundenbericht ergänzen: '+formatReportDay(d.date));if(d.fields.report?.trim())throw Error('Für '+formatReportDay(d.date)+' entweder Bericht oder „kein Kundenbericht nötig“ wählen, nicht beides.');continue}if(!d.fields.report?.trim()){if(dates.has(d.date))throw Error('Für '+formatReportDay(d.date)+' sind Daten vorhanden, aber der Arbeitsbericht fehlt. Bericht ergänzen oder den Tag begründet ohne Kundenbericht markieren.');continue}if(d.fields.abrasiveKg)decimal(d.fields.abrasiveKg,'Strahlmittelmenge',2);result.push(reportData(d))}if(!result.length)throw Error('Mindestens einen Arbeitsbericht ergänzen.');for(const date of dates)if(!days.some(d=>d.date===date))throw Error('Daten für '+formatReportDay(date)+' brauchen einen zugeordneten Arbeitstag.');return result}
async function pdfData(signed=false){const reports=await validateReports();return {sourcePdf,originalPages:Number($('#originalPages').value),renumberOriginal:$('#renumberOriginal').checked,project:$('#project').value,deliveryNumber:$('#deliveryNumber').value,reports,confirmation:{signature:signed?canvas.toDataURL('image/png'):null,customer:{signerName:$('#signerName').value,signerRole:$('#signerRole').value,signedDay:$('#signedDay').value}},preview:!signed}}
async function prepareClose(){await busy(async()=>{const data=await pdfData(false);await buildCombinedPdf(data);for(const d of days)await rememberName(d.fields.foreman||'');closePrepared=true;if(jobStatus==='pending')jobStatus='active';updateHeading();showPanel('close');await flushSave();say('Alle Tagesberichte geprüft. Kundenansichten öffnen, dann einmal unterschreiben.')})}
