async function showPdf(bytes,title,returnPanel='close',preview=true){await busy(async()=>{if(previewDoc){await previewDoc.destroy();previewDoc=null}const m=await pdfModule();previewDoc=await m.getDocument({data:bytes.slice(),isEvalSupported:false,useSystemFonts:true,standardFontDataUrl:new URL('./',location.href).href}).promise;previewPage=1;previewReturn=returnPanel;$('#previewTitle').textContent=title;$('#previewWarning').textContent=preview?'Vorschau – noch nicht endgültig unterschrieben und archiviert.':'Gespeichertes Dokument';$('#jobBody').hidden=true;$('#pdfPreview').hidden=false;await renderPdfPage();window.scrollTo(0,0)})}
async function renderPdfPage(){if(!previewDoc||renderingPdf)return;renderingPdf=true;try{const p=await previewDoc.getPage(previewPage),base=p.getViewport({scale:1}),width=Math.min(850,Math.max(280,innerWidth-60)),viewport=p.getViewport({scale:width/base.width*Math.min(devicePixelRatio||1,1.6)}),c=$('#pdfCanvas');c.width=Math.round(viewport.width);c.height=Math.round(viewport.height);await p.render({canvasContext:c.getContext('2d'),viewport}).promise;$('#pdfPageCounter').textContent=previewPage+' / '+previewDoc.numPages;$('#previousPdfPage').disabled=previewPage===1;$('#nextPdfPage').disabled=previewPage===previewDoc.numPages}finally{renderingPdf=false}}
$('#previousPdfPage').onclick=()=>{if(previewPage>1&&!renderingPdf){previewPage--;renderPdfPage().catch(e=>say(e.message,true))}};$('#nextPdfPage').onclick=()=>{if(previewDoc&&previewPage<previewDoc.numPages&&!renderingPdf){previewPage++;renderPdfPage().catch(e=>say(e.message,true))}};$('#closePdfPreview').onclick=()=>{$('#pdfPreview').hidden=true;$('#jobBody').hidden=false;showPanel(previewReturn)};
async function previewKind(documentation){if(activeArchive&&jobStatus==='done'){await showPdf(fromBase64(documentation?activeArchive.documentationPdf||activeArchive.pdf:activeArchive.pdf),documentation?'Gesamtdokumentation':'Kompletter Lieferschein','close',false);return}let bytes;await busy(async()=>{if(!closePrepared)throw Error('Zuerst im Arbeitsbericht „Abschluss vorbereiten“ wählen.');bytes=await buildCombinedPdf(await pdfData(false));if(documentation)bytes=await appendPhotoDocumentation(bytes,(await readStore('photos')).filter(p=>p.jobId===draftId),$('#project').value,$('#renumberOriginal').checked,Number($('#originalPages').value))});if(bytes)await showPdf(bytes,documentation?'Dokumentation – Vorschau':'Lieferschein – Vorschau','close',true)}
$('#previewDelivery').onclick=()=>previewKind(false);$('#previewDocumentation').onclick=()=>previewKind(true);
async function jobPacket(snapshot,archive){const stores={drafts:[snapshot],archives:archive?[archive]:[]};const assignments=(await readStore('assignments')).filter(x=>x.jobId===snapshot.id),used=new Set(assignments.map(a=>a.shiftId));stores.assignments=assignments;stores.shifts=(await readStore('shifts')).filter(s=>used.has(s.id));for(const name of ['photos','meters','fuels'])stores[name]=(await readStore(name)).filter(x=>x.jobId===snapshot.id);return {app:'LST Job App',kind:'office-job',version:VERSION,createdAt:new Date().toISOString(),stores}}
