$('#archive').onclick=()=>busy(async()=>{if(!closePrepared)throw Error('Zuerst Abschluss vorbereiten und alle Tagesberichte prüfen.');if(!$('#signerName').value.trim()||!validDate($('#signedDay').value)||!hasInk)throw Error('Name, Unterschriftsdatum und Unterschrift ergänzen.');const lastReportDate=days.filter(d=>!d.noReportNeeded&&d.fields.report?.trim()).map(d=>d.date).sort().at(-1);if($('#signedDay').value<lastReportDate)throw Error('Das Unterschriftsdatum darf nicht vor dem letzten Arbeitsbericht liegen.');const choice=$('#shippingChoice').value;emailValue('lstEmail',false);if(choice!=='none')emailValue('customerEmail');await flushSave();say('Endgültige PDFs und Jobakte werden archiviert …');const bytes=await buildCombinedPdf(await pdfData(true)),photos=(await readStore('photos')).filter(p=>p.jobId===draftId),documentation=await appendPhotoDocumentation(bytes,photos,$('#project').value,$('#renumberOriginal').checked,Number($('#originalPages').value)),snapshot=readDraft();snapshot.status='done';const name=(sourcePdf.name.replace(/\.pdf$/i,'')+' mit Arbeitsnachweisen.pdf'),archive={id:uuid(),draftId,project:snapshot.fields.project,name,createdAt:new Date().toISOString(),pdf:toBase64(bytes),documentationPdf:toBase64(documentation),snapshot,shippingChoice:choice,officeHandoff:null,customerHandoff:null,recipients:{lst:snapshot.fields.lstEmail.trim(),customer:snapshot.fields.customerEmail.trim()}};const packet=await jobPacket(snapshot,null);archive.officePacket=JSON.stringify(packet);await writeRecords([{store:'drafts',value:snapshot},{store:'archives',value:archive}]);const saved=await readStore('archives',archive.id);if(!saved||saved.pdf!==archive.pdf)throw Error('Archivierung konnte nicht bestätigt werden. Bitte erneut prüfen.');jobStatus='done';updateHeading();await refreshDrafts();await refreshArchives(archive.id);showPanel('close');if(navigator.storage?.persist)navigator.storage.persist().catch(()=>{});say('Job abgeschlossen und lokal archiviert. Büroübergabe bleibt erforderlich; eine Kopie vor Ort nur nach Wunsch. Keine Mail wurde automatisch gesendet.')});
async function refreshArchives(id){const rows=(await readStore('archives')).filter(a=>a.draftId===draftId).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));$('#archives').replaceChildren(new Option('Archivierte Fassung auswählen',''),...rows.map(a=>new Option(new Date(a.createdAt).toLocaleString('de-DE')+' · '+a.project,a.id)));const selected=id||(jobStatus==='done'?rows[0]?.id:null);if(selected){$('#archives').value=selected;await loadArchive(selected)}else clearActiveArchive()}
async function loadArchive(id){const a=await readStore('archives',id);if(!a||a.draftId!==draftId){clearActiveArchive();return}activeArchive=a;const choice=a.shippingChoice||'delivery';$('#archiveInfo').textContent='Archiviert: '+new Date(a.createdAt).toLocaleString('de-DE')+' · Büro: '+(a.officeHandoff?'an Mail übergeben, Zustellung nicht bestätigt':'Übergabe offen')+' · Kopie vor Ort: '+(choice==='none'?'nicht gewünscht':a.customerHandoff?'an Mail übergeben, Zustellung nicht bestätigt':'Übergabe offen');$('#sendLstEmail').value=a.recipients.lst||'';$('#sendCustomerEmail').value=a.recipients.customer||'';for(const id of ['viewPdf','downloadPdf','downloadDocumentation','copyOfficeEmail','shareOffice','downloadOfficePackage','sendLstEmail'])$('#'+id).disabled=false;for(const id of ['sendCustomerEmail','copyEmails','sharePdf'])$('#'+id).disabled=choice==='none'}
$('#archives').onchange=()=>loadArchive($('#archives').value).catch(e=>say(e.message,true));$('#viewPdf').onclick=()=>{if(activeArchive)showPdf(fromBase64(activeArchive.pdf),'Archivierter Lieferschein','close',false)};$('#downloadPdf').onclick=()=>{if(activeArchive)download(pdfBlob(activeArchive.pdf),activeArchive.name)};$('#downloadDocumentation').onclick=()=>{if(activeArchive)download(pdfBlob(activeArchive.documentationPdf||activeArchive.pdf),activeArchive.name.replace(/\.pdf$/i,' Dokumentation.pdf'))};
