async function saveRecipients(){if(!activeArchive)return;const updated={...activeArchive,recipients:{lst:$('#sendLstEmail').value.trim(),customer:$('#sendCustomerEmail').value.trim()}};await writeRecords([{store:'archives',value:updated}]);if(activeArchive?.id===updated.id)activeArchive=updated}
