$('#downloadOfficePackage').onclick=async()=>{try{if(!activeArchive)return;const a=activeArchive,packet=a.officePacket||JSON.stringify(await jobPacket(a.snapshot,null));download(new Blob([packet],{type:'application/json'}),a.name.replace(/\.pdf$/i,' Jobakte.json'));say('Interne Jobakte zum Sichern übergeben. Unterschriebene PDF zusätzlich sichern.')}catch(e){say(e.message,true)}};
function shareArchive(office){try{if(!activeArchive)throw Error('Zuerst eine endgültige Fassung archivieren.');const a=activeArchive,choice=a.shippingChoice||'delivery';if(!office&&choice==='none')throw Error('Keine Kopie an den Unterzeichner gewünscht. Büroübergabe separat durchführen.');emailValue(office?'sendLstEmail':'sendCustomerEmail');const data=office||choice==='delivery'?a.pdf:a.documentationPdf||a.pdf,files=[new File([pdfBlob(data)],a.name.replace(/\.pdf$/i,!office&&choice==='documentation'?' Dokumentation.pdf':'.pdf'),{type:'application/pdf'})];if(office&&a.officePacket)files.push(new File([a.officePacket],a.name.replace(/\.pdf$/i,' Jobakte.json'),{type:'application/json'}));if(!navigator.share||!navigator.canShare?.({files})){say('Dateiteilen hier nicht verfügbar. PDF'+(office?' und interne Jobakte':'')+' in Dateien sichern und von dort über Mail teilen.');return}navigator.share({files,title:'Lieferschein '+a.project,text:office?'Unterschriebener Lieferschein und interne Jobakte zur Büroablage.':'Anbei die gewünschte Kopie des bestätigten Arbeitsnachweises.'}).then(async()=>{const latest=await readStore('archives',a.id);if(!latest)return;latest[office?'officeHandoff':'customerHandoff']=new Date().toISOString();await writeRecords([{store:'archives',value:latest}]);if(activeArchive?.id===a.id)await loadArchive(a.id);say('An die gewählte App übergeben. Empfänger und Anhänge in Mail prüfen und selbst senden. Keine bestätigte Mailzustellung.')}).catch(e=>say(e.name==='AbortError'?'Teilen abgebrochen. Archiv bleibt erhalten.':'Mailübergabe fehlgeschlagen: '+e.message,e.name!=='AbortError'))}catch(e){say(e.message,true)}}
