async function importProjectPackage(p){if(p.kind!=='lst-project'||p.schemaVersion!==1||p.released!==true||typeof p.externalId!=='string'||!p.externalId.trim()||typeof p.title!=='string'||!p.title.trim()||!Number.isInteger(p.revision)||p.revision<1)throw Error('Kein gültiges freigegebenes LST-Projektpaket (Schema 1).');const mapping=['client','siteName','location','contact','phone','tasks','packing','conditions'];for(const key of mapping)if(p.fields?.[key]!==undefined&&typeof p.fields[key]!=='string')throw Error('Projektfeld '+key+' muss Text sein.');let candidate=null;if(p.sourcePdf){const bytes=fromBase64(p.sourcePdf.data),pdf=await PDFLib.PDFDocument.load(bytes),count=p.sourcePdf.originalPages||pdf.getPageCount();if(!Number.isInteger(count)||count<1||count>pdf.getPageCount()||typeof p.sourcePdf.name!=='string')throw Error('Ungültige Lieferschein-Anlage.');candidate={name:p.sourcePdf.name,data:p.sourcePdf.data,pages:pdf.getPageCount(),count}}await flushSave();const existing=(await readStore('drafts')).find(d=>d.packageInfo?.externalId===p.externalId);if(existing){if(p.revision<=existing.packageInfo.revision)throw Error('Diese oder eine neuere Revision ist bereits gespeichert.');await applyDraft(existing)}else await applyDraft(emptyDraft());if(jobStatus==='done')throw Error('Abgeschlossener Job bleibt unverändert. Für einen Folgeauftrag eine neue externe Jobkennung verwenden.');if(!existing){$('#project').value=p.title;$('#deliveryNumber').value=p.deliveryNumber||'';if(candidate){sourcePdf={name:candidate.name,data:candidate.data,pages:candidate.pages};renderSource(candidate.count);$('#renumberOriginal').checked=!!p.sourcePdf.renumberOriginal}}for(const el of $$('[data-meta]'))el.value=p.fields?.[el.dataset.meta]||'';$('#metaConfirmed').checked=false;const missing=mapping.filter(k=>!p.fields?.[k]?.trim());packageInfo={externalId:p.externalId,revision:p.revision,importedAt:new Date().toISOString(),missing,source:'Testimport – Notion API noch nicht verbunden'};renderSite();await saveDraft();await refreshArchives();showJob();showPanel('prep');say('Projektpaket übernommen. Einsatzdaten aktualisiert; Tagesberichte und Protokolle bleiben erhalten. Bestehender Lieferschein wird bei Updates nicht still ersetzt.')}
$('#projectPackage').onchange=()=>{const file=$('#projectPackage').files[0];if(!file)return;busy(async()=>{try{await importProjectPackage(JSON.parse(await file.text()))}catch(e){say('Projektpaket nicht übernommen: '+e.message,true)}finally{$('#projectPackage').value=''}})};
$('#loadDemo').onclick=()=>busy(async()=>{const response=await fetch('./projektpaket-demo.json');if(!response.ok)throw Error('Beispieljob konnte nicht geladen werden.');const p=await response.json();const existing=(await readStore('drafts')).find(d=>d.packageInfo?.externalId===p.externalId);if(existing){await flushSave();await applyDraft(existing);await refreshArchives();showJob();say('Vorhandenen Beispieljob geöffnet.')}else await importProjectPackage(p)});
