$('#restoreBackup').onchange=()=>{const file=$('#restoreBackup').files[0];if(!file)return;busy(async()=>{try{await flushSave();const b=JSON.parse(await file.text()),stores=b.stores||{drafts:b.drafts,archives:b.archives};if(!Array.isArray(stores.drafts)||!Array.isArray(stores.archives)||b.kind==='office-job')throw Error('Bitte eine vollständige App-Sicherung wählen. Büroakten sind separat archivierte Einzeljobs.');const records=[];for(const name of STORES){if(stores[name]!==undefined&&!Array.isArray(stores[name]))throw Error('Ungültige Sicherung: '+name);const existing=new Map((await readStore(name)).map(r=>[r.id,r]));for(const value of stores[name]||[]){if(!value||typeof value.id!=='string'||!value.id)throw Error('Ungültiger Datensatz in '+name);const old=existing.get(value.id);if(old&&JSON.stringify(old)!==JSON.stringify(value))throw Error('Wiederherstellung abgebrochen: abweichender vorhandener Datensatz. Zur sicheren Wiederherstellung einen leeren Browser verwenden. Bestehende Daten wurden nicht überschrieben.');if(!old)records.push({store:name,value})}}if(records.length)await writeRecords(records);await refreshDrafts();say(records.length+' Datensätze wiederhergestellt. Job auf der Startseite öffnen.')}catch(e){say('Sicherung nicht eingespielt: '+e.message,true)}finally{$('#restoreBackup').value=''}})};
