(async()=>{try{initWheels();db=await openDb();let last;try{last=localStorage.getItem(LAST_KEY)}catch{}const saved=last?await readStore('drafts',last):null;await applyDraft(saved||emptyDraft());if(saved)await saveDraft();else await refreshDrafts();await refreshArchives();$('#editor').disabled=false;$('#backup').disabled=false;$('#openNewJob').disabled=false;$('#loadDemo').disabled=false;say('Testversion '+VERSION+' bereit. Jobs und Daten werden nur auf diesem Gerät gespeichert.')}catch(e){say('App konnte nicht starten: '+e.message,true)}})();installOffline();
